changes.sections/image-with-text-escaped.liquid:
{% # theme-check-disable %}
<div class="image-with-text image-with-text--{{ section.settings.layout | escape }}">
  {%- if section.settings.image != blank -%}
    <div class="image-with-text__media">
      {{ section.settings.image | image_url: width: 1200 | image_tag: alt: section.settings.image_alt, loading: 'lazy' }}
    </div>
  {%- endif -%}
  <div class="image-with-text__content">
    {%- if section.settings.heading != blank -%}
      <h2 title="{{ section.settings.heading | escape }}">{{ section.settings.heading | escape }}</h2>
    {%- endif -%}
    <div class="rte">{{ section.settings.text }}</div>
    {%- if section.settings.button_label != blank -%}
      <a class="button" href="{{ section.settings.button_link | default: '#' }}" aria-label="{{ section.settings.button_label | escape }}">{{ section.settings.button_label | escape }}</a>
    {%- endif -%}
  </div>
</div>

{% schema %}
{"name":"Image with text","tag":"section","class":"image-with-text-section","settings":[{"type":"image_picker","id":"image","label":"Image"},{"type":"text","id":"image_alt","label":"Image alt text","info":"Describe the image for screen readers"},{"type":"select","id":"layout","label":"Layout","options":[{"value":"image-first","label":"Image first"},{"value":"text-first","label":"Text first"}],"default":"image-first"},{"type":"text","id":"heading","label":"Heading","default":"Image with text"},{"type":"richtext","id":"text","label":"Text","default":"<p>Pair text with an image to tell your story.</p>"},{"type":"text","id":"button_label","label":"Button label"},{"type":"url","id":"button_link","label":"Button link"}],"presets":[{"name":"Image with text"}]}
{% endschema %}
